"""Coverage calibration, exact scoring, filtering and priority (contract v3)."""
from fractions import Fraction
import numpy as np

PAD = 1514
MAX_VALUE = 3028


def real_prefix_length(values):
    try:
        return values.index(PAD)
    except ValueError:
        return len(values)


def _row_match_masks(clusters, val_rows, n_classes):
    """hits[cluster-index][class] = number of matching validation rows.

    A row matches a generalized interval pattern iff some contiguous
    real-prefix window of the pattern length lies inside every inclusive
    interval; the row counts once per pattern."""
    hits = [[0]*n_classes for _ in clusters]
    if not clusters:
        return hits
    by_len = {}
    for idx, c in enumerate(clusters):
        by_len.setdefault(len(c['range']), []).append(idx)
    structures = {}
    for L, idxs in by_len.items():
        chunks = (len(idxs) + 63)//64
        V = np.zeros((L, MAX_VALUE+1, chunks), dtype=np.uint64)
        for i, ci in enumerate(idxs):
            bit = np.uint64((1 << (i % 64)) & 0xFFFFFFFFFFFFFFFF)
            c = i//64
            for j, (lo, hi) in enumerate(clusters[ci]['range']):
                V[j, lo:hi+1, c] |= bit
        structures[L] = (idxs, chunks, V)
    collected = {L: {} for L in structures}
    for row in val_rows:
        vals = row['values']
        R = real_prefix_length(vals)
        cls = row['class']
        F = np.asarray(vals[:R], dtype=np.int64)
        for L, (idxs, chunks, V) in structures.items():
            Wn = R - L + 1
            if Wn <= 0:
                continue
            acc = V[0][F[0:Wn], :].copy()
            for j in range(1, L):
                acc &= V[j][F[j:j+Wn], :]
                if not acc.any():
                    break
            if not acc.any():
                continue
            rm = np.bitwise_or.reduce(acc, axis=0)
            if rm.any():
                collected[L].setdefault(cls, []).append(rm)
    for L, (idxs, chunks, V) in structures.items():
        for cls, lst in collected[L].items():
            mat = np.stack(lst)
            bits = np.unpackbits(mat.view(np.uint8), axis=1, bitorder='little')[:, :len(idxs)]
            counts = bits.sum(axis=0)
            for i, ci in enumerate(idxs):
                hits[ci][cls] = int(counts[i])
    return hits


def calibrate(clusters, val_rows, n_classes, threshold):
    """Fill hits/score/kept on every cluster; return priority list.

    score = Cin/(Cout+1/10000) as an exact reduced fraction; kept iff
    score > threshold exactly.  Priority: decreasing exact score, then
    increasing cluster ID."""
    N = [0]*n_classes
    for row in val_rows:
        N[row['class']] += 1
    hits = _row_match_masks(clusters, val_rows, n_classes)
    threshold = Fraction(threshold[0], threshold[1])
    for i, c in enumerate(clusters):
        t = c['class']
        h = hits[i]
        cin = Fraction(h[t], N[t])
        cout = Fraction(0)
        for cls in range(n_classes):
            if cls != t:
                cand = Fraction(h[cls], N[cls])
                if cand > cout:
                    cout = cand
        score = cin/(cout + Fraction(1, 10000))
        c['hits'] = h
        c['score'] = score
        c['kept'] = score > threshold
    kept = [c for c in clusters if c['kept']]
    kept.sort(key=lambda c: (-c['score'], c['id']))
    return [c['id'] for c in kept]
